import{_ as a,o,c as e,ai as n}from"./chunks/framework.BBSijY9B.js";const u=JSON.parse('{"title":"用量不经花？让 Bot 当工头，别当苦力：三层分工法","description":"","frontmatter":{"date":"2026-10-21T00:00:00.000Z","title":"用量不经花？让 Bot 当工头，别当苦力：三层分工法","summary":"例程先做一步便宜的检查，机械的活写成脚本，定型的重活外包给 CLI 编程助手，Bot 只管判断、派活和验收。附一段让 Bot 自查例程的提示词。","category":"方法论","tags":["用量","例程","自动化","多 Bot"],"sources":[{"url":"https://x.com/eze_is_1/status/2109850538045264151","author":"@eze_is_1（10 条必备经验）","platform":"X"},{"url":"https://github.com/robbin/grokbot-local-agent","author":"robbin/grokbot-local-agent（GitHub）","platform":"GitHub"},{"url":"https://x.com/fankaishuoai/status/2112396515801284647","author":"@fankaishuoai","platform":"X"},{"url":"https://x.com/MikeysMolecules/status/2112274232444850331","author":"@MikeysMolecules","platform":"X"}],"updates":[{"link":"/faq/faq","title":"常见问题：「怎么省用量」补充三层分工"},{"link":"/automation/routines","title":"例程：新增「先做一步便宜的检查」和「用 Webhook 等长任务」"},{"link":"/resources/?tab=projects","title":"资源导航 · 开源项目：新增 grokbot-local-agent"}],"wordCount":792,"readingTime":2,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"用量不经花？让 Bot 当工头，别当苦力：三层分工法 | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"例程先做一步便宜的检查，机械的活写成脚本，定型的重活外包给 CLI 编程助手，Bot 只管判断、派活和验收。附一段让 Bot 自查例程的提示词。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/daily/2026-10-21-bot-as-foreman"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/daily-2026-10-21-bot-as-foreman-3af90f5775.png"}],["meta",{"property":"og:image:alt","content":"用量不经花？让 Bot 当工头，别当苦力：三层分工法 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"用量不经花？让 Bot 当工头，别当苦力：三层分工法 | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"例程先做一步便宜的检查，机械的活写成脚本，定型的重活外包给 CLI 编程助手，Bot 只管判断、派活和验收。附一段让 Bot 自查例程的提示词。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/daily-2026-10-21-bot-as-foreman-3af90f5775.png"}],["meta",{"name":"twitter:image:alt","content":"用量不经花？让 Bot 当工头，别当苦力：三层分工法 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/daily/2026-10-21-bot-as-foreman"}]]},"headers":[],"relativePath":"daily/2026-10-21-bot-as-foreman.md","filePath":"daily/2026-10-21-bot-as-foreman.md","lastUpdated":1792514041000}'),s={name:"daily/2026-10-21-bot-as-foreman.md"};function r(i,t,l,p,c,d){return o(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="用量不经花-让-bot-当工头-别当苦力-三层分工法" tabindex="-1">用量不经花？让 Bot 当工头，别当苦力：三层分工法 <a class="header-anchor" href="#用量不经花-让-bot-当工头-别当苦力-三层分工法" aria-label="Permalink to &quot;用量不经花？让 Bot 当工头，别当苦力：三层分工法&quot;">​</a></h1><p>这两天 X 上&quot;Grok Bot 不经花&quot;的抱怨很多。几位重度用户不约而同给出了同一个思路：<strong>Bot 最值钱的是判断、连接各种 App 和跟你沟通，不是闷头干体力活</strong>。体力活交出去，Bot 只派活、验收。</p><p>下面按&quot;从最省事到最费事&quot;排成三层，从第一层做起就有效果。</p><h2 id="第一层-给每个例程加一步-便宜的检查" tabindex="-1">第一层：给每个例程加一步&quot;便宜的检查&quot; <a class="header-anchor" href="#第一层-给每个例程加一步-便宜的检查" aria-label="Permalink to &quot;第一层：给每个例程加一步&quot;便宜的检查&quot;&quot;">​</a></h2><p><a href="https://x.com/MikeysMolecules/status/2112274232444850331" target="_blank" rel="noopener noreferrer">@MikeysMolecules</a> 的建议：例程在调研、写稿、出图之前，<strong>先检查一下有没有新东西，没有就安静结束</strong>。平淡的日子里，大部分运行到这一步就停了，省下的就是这些。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>修改&quot;竞品动态&quot;例程：第一步只检查 A、B、C 三家的更新页和官方账号，</span></span>
<span class="line"><span>和上次运行记录比，没有新内容就回复一句&quot;今日无更新&quot;后结束，不要继续调研和写稿。</span></span>
<span class="line"><span>有新内容才进入后面的步骤。</span></span></code></pre></div><h2 id="第二层-能写成脚本的-就别让-ai-每次重想" tabindex="-1">第二层：能写成脚本的，就别让 AI 每次重想 <a class="header-anchor" href="#第二层-能写成脚本的-就别让-ai-每次重想" aria-label="Permalink to &quot;第二层：能写成脚本的，就别让 AI 每次重想&quot;">​</a></h2><p><a href="https://x.com/eze_is_1/status/2109850538045264151" target="_blank" rel="noopener noreferrer">@eze_is_1</a> 在他的 10 条经验里举的例子：「每天去某个网站读一个数，跟前一天比有没有变化」，这种事根本不需要 AI 每次去想，<strong>写成一个普通脚本定时跑，只把变化的部分交给 Bot</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把&quot;每天查 X 价格&quot;这件事改成脚本：你写一个 Python 脚本，抓数、和昨天比、</span></span>
<span class="line"><span>把结果追加到 data/prices.csv。脚本每天 8:00 跑，只有变化超过 5% 时才通知你，</span></span>
<span class="line"><span>你再来分析和告诉我。脚本写好先跑一次给我看输出。</span></span></code></pre></div><p>规则一旦定型，脚本每次都一样，不会&quot;今天理解偏了&quot;，也几乎不花 Bot 的用量。</p><h2 id="第三层-定型的重活-外包给-cli-编程助手" tabindex="-1">第三层：定型的重活，外包给 CLI 编程助手 <a class="header-anchor" href="#第三层-定型的重活-外包给-cli-编程助手" aria-label="Permalink to &quot;第三层：定型的重活，外包给 CLI 编程助手&quot;">​</a></h2><p>已经跑顺、有明确验收标准的活（批量改文件、写代码、长文档初稿），可以让 Bot 在电脑上调用 Codex CLI、Claude Code 这类命令行编程助手去做，<strong>用的是你在那边的订阅或 API 额度</strong>。Bot 只负责写清任务、派出去、验收结果。</p><p>两个现成的开源做法：</p><ul><li><a href="https://github.com/robbin/grokbot-local-agent" target="_blank" rel="noopener noreferrer">robbin/grokbot-local-agent</a>（<a href="https://x.com/fankaishuoai/status/2112396515801284647" target="_blank" rel="noopener noreferrer">@fankaishuoai</a> 分享）：让 Bot 把活交给它云电脑上的 Pi 编程助手。每个任务有编号、状态和产物文件，<strong>以磁盘上的状态为准</strong>，通知漏了也能补查，不会重复跑。作者自己用三层：Grok Bot 负责沟通、编排和验收；Pi 做批量修改、小脚本和初稿；更大的长期项目交给云端编程 Agent。</li><li><a href="/daily/2026-10-21-wake-on-done">Wake on Done</a>：任务跑完自动叫醒派活的 Bot，不用它反复去看。</li></ul><p>派活时一定写清<strong>交付物和验收标准</strong>，比如&quot;结果写到哪个文件、测试要全过、diff 里不许动哪些目录&quot;。验收是 Bot 必须亲自做的那一步。</p><h2 id="什么留给-bot-自己做" tabindex="-1">什么留给 Bot 自己做 <a class="header-anchor" href="#什么留给-bot-自己做" aria-label="Permalink to &quot;什么留给 Bot 自己做&quot;">​</a></h2><table tabindex="0"><thead><tr><th>留给 Bot</th><th>交出去</th></tr></thead><tbody><tr><td>跟你沟通、追问需求</td><td>规则固定的抓数、比对</td></tr><tr><td>用连接器读写邮箱、日历、文档</td><td>批量改文件、写代码、跑测试</td></tr><tr><td>拿不准的判断、需要审批的动作</td><td>已有模板的长文初稿</td></tr><tr><td>最后的验收和汇报</td><td>耗时的构建、抓取</td></tr></tbody></table><h2 id="先让-bot-自查一遍" tabindex="-1">先让 Bot 自查一遍 <a class="header-anchor" href="#先让-bot-自查一遍" aria-label="Permalink to &quot;先让 Bot 自查一遍&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>检查我所有 Bot 的所有例程，逐个列出：频率、每次大概做哪些步骤、</span></span>
<span class="line"><span>有没有&quot;先检查有没有新内容&quot;这一步、哪些步骤其实可以改成脚本。</span></span>
<span class="line"><span>给出合并、降频、加检查步骤的建议，按预计省得多少排序。先出方案，等我确认再改。</span></span></code></pre></div><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><ul><li>外部 CLI 工具要用你自己的账号登录，遵守那边的服务条款；<strong>登录凭证放在共用的云电脑上，所有 Bot 都能用到</strong>。</li><li>交出去的活出了错，Bot 要能看到。所以第三层一定配合验收标准和&quot;跑完叫醒&quot;一起用，别让任务有去无回。</li></ul>`,21)])])}const g=a(s,[["render",r]]);export{u as __pageData,g as default};
